"use client";

import React, { useState, useEffect, useCallback } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";

const baseLogos = [{"name": "Hilton", "src": "data:image/jpeg;base64,"}, {"name": "M\u00f6venpick", "src": "data:image/jpeg;base64,"}, {"name": "Pakistan International Airlines", "src": "data:image/jpeg;base64,"}, {"name": "Zee Overseas", "src": "data:image/jpeg;base64,"}, {"name": "Saudi Tourism Authority", "src": "data:image/jpeg;base64,"}, {"name": "Swiss\u00f4tel Al Maqam Makkah", "src": "data:image/jpeg;base64,"}, {"name": "Royal Jordanian", "src": "data:image/jpeg;base64,"}, {"name": "Emaar Al Diyafa Hotels", "src": "data:image/jpeg;base64,"}, {"name": "Etihad Airways", "src": "data:image/jpeg;base64,"}, {"name": "Turkish Airlines", "src": "data:image/jpeg;base64,"}, {"name": "Partner", "src": "data:image/jpeg;base64,"}, {"name": "Dar Al Eiman Co.", "src": "data:image/jpeg;base64,"}];
const VISIBLE = 4;
// Clone the first VISIBLE logos onto the end for a seamless infinite loop
const logos = baseLogos.concat(baseLogos.slice(0, VISIBLE));

export default function PartnersCarousel() {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [noTransition, setNoTransition] = useState(false);

  const total = baseLogos.length; // number of real logos

  const next = useCallback(() => {
    setIndex((prev) => prev + 1);
  }, []);

  const prev = useCallback(() => {
    setIndex((prevIdx) => (prevIdx === 0 ? 0 : prevIdx - 1));
  }, []);

  // Auto-slide, one logo at a time
  useEffect(() => {
    if (paused) return;
    const timer = setInterval(() => {
      next();
    }, 2000);
    return () => clearInterval(timer);
  }, [paused, next]);

  // When we scroll past the last real logo, snap back to start without animation
  useEffect(() => {
    if (index === total) {
      const timeout = setTimeout(() => {
        setNoTransition(true);
        setIndex(0);
      }, 600);
      return () => clearTimeout(timeout);
    }
  }, [index, total]);

  useEffect(() => {
    if (noTransition) {
      const raf = requestAnimationFrame(() => {
        requestAnimationFrame(() => setNoTransition(false));
      });
      return () => cancelAnimationFrame(raf);
    }
  }, [noTransition]);

  const dotActiveIndex = index % total;
  const itemWidthPct = 100 / VISIBLE;

  return (
    <section className="w-full bg-white py-14 sm:py-20 px-4">
      <div className="max-w-2xl mx-auto text-center mb-10 sm:mb-14">
        <h2 className="text-3xl sm:text-3xl md:text-3xl font-extrabold text-[#1F2937] tracking-tight">
          We are partners with
        </h2>
        <p className="mt-3 text-sm sm:text-base text-[#6B7280]">
          Trusted global partners for years
        </p>
      </div>

      <div
        className="relative max-w-6xl mx-auto flex items-center gap-2 sm:gap-4"
        onMouseEnter={() => setPaused(true)}
        onMouseLeave={() => setPaused(false)}
      >
        <button
          onClick={prev}
          aria-label="Previous partner"
          className="shrink-0 w-9 h-9 sm:w-12 sm:h-12   text-white flex items-center justify-center transition-colors duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#374151] focus-visible:ring-offset-2 z-10"
        >
          <ChevronLeft size={20} />
        </button>

        <div className="flex-1 overflow-hidden">
          <div
            className="flex"
            style={{
              transform: `translateX(-${index * itemWidthPct}%)`,
              transition: noTransition ? "none" : "transform 600ms ease-in-out",
            }}
          >
            {logos.map((logo, i) => (
              <div
                key={i}
                className="shrink-0 flex items-center justify-center px-2 sm:px-4"
                style={{ width: `${itemWidthPct}%` }}
              >
                <div className="  flex items-center justify-center p-3 sm:p-6 h-24 sm:h-40 w-full">
                  <img
                    src={logo.src}
                    alt={logo.name}
                    title={logo.name}
                    className="max-h-full max-w-full object-contain"
                  />
                </div>
              </div>
            ))}
          </div>
        </div>

        <button
          onClick={next}
          aria-label="Next partner"
          className="shrink-0 w-9 h-9 sm:w-12 sm:h-12 rounded-full  text-white flex items-center justify-center transition-colors duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#374151] focus-visible:ring-offset-2 z-10"
        >
          <ChevronRight size={20} />
        </button>
      </div>

      <div className="flex items-center justify-center gap-1.5 mt-8 sm:mt-10">
        {baseLogos.map((_, i) => (
          <button
            key={i}
            onClick={() => setIndex(i)}
            aria-label={`Go to partner ${i + 1}`}
            className={`h-1.5 rounded-full transition-all duration-300 ${
              i === dotActiveIndex ? "w-6" : "w-1.5 bg-[#D1D5DB]"
            }`}
          />
        ))}
      </div>
    </section>
  );
}